+    }
+
+    private void trySend() {
+        if (!send.isEnabled() || !validate()) {
+            return;
+        }
+
+        store.add(new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue().trim()));
+        sentMessages.setItems(store.all());
+
+        clearForm();
+        send.setEnabled(false);
+
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+    }
+
+    /**
+     * Marks every field a rule fails on, and tells why.
+     *
+     * @return true when the form may be sent
+     */
+    private boolean validate() {
+        clearErrors();
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue();
+
+        boolean valid = true;
+
+        if (nameValue.isEmpty()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.trim().isEmpty()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message,
+                    "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (HasValidation field : fields()) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    private void clearForm() {
+        clearingForm = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+            clearErrors();
+        } finally {
+            clearingForm = false;
+        }
+    }
+
+    /** True when there is something in the form that leaving would throw away. */
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard this message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Span("The message you have written has not been sent yet."));
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
