@@ -0,0 +1,43 @@
+package com.example.views;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * The messages sent so far, newest first. Kept in the Vaadin session, so that
+ * leaving the contact view and coming back still shows them.
+ */
+public class MessageStore implements Serializable {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    /**
+     * The store of the current session, created on first use.
+     */
+    public static MessageStore get() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            // No session at hand (e.g. a plain unit test); give a scratch store
+            // rather than failing.
+            return new MessageStore();
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+
+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    /** The messages, newest first. */
+    public List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+}
