@@ -0,0 +1,201 @@
+package com.example.views;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * The same behaviour, checked in a real browser. Named *IT so that the normal
+ * {@code mvn test} run stays fast; run it with
+ * {@code mvn -o test -Dtest=ContactViewIT -DfailIfNoTests=false}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private void assertHeading(String text) {
+        com.microsoft.playwright.assertions.PlaywrightAssertions
+                .assertThat(page.locator("h1")).hasText(text);
+    }
+
+    private void clickLink(String text) {
+        page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName(text)).click();
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private void fillValidForm() {
+        name().setValue("Jane");
+        email().setValue("jane@example.com");
+        message().setValue("Hello there");
+    }
+
+    @Test
+    void headingLinkAndEmptyEnabledForm() {
+        assertHeading("Contact");
+        assertTrue(page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).isVisible());
+        assertEquals("", name().getValue());
+        assertEquals("", message().getValue());
+        send().assertEnabled();
+    }
+
+    @Test
+    void emptyFormShowsEveryError() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        GridElement.get(page).assertEmpty();
+        send().assertEnabled();
+    }
+
+    @Test
+    void badEmailIsRejected() {
+        name().setValue("Jane");
+        email().setValue("nope");
+        message().setValue("Hi");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        GridElement.get(page).assertEmpty();
+        assertEquals("Jane", name().getValue());
+    }
+
+    @Test
+    void longMessageIsRejected() {
+        name().setValue("Jane");
+        phone().setValue("123456");
+        message().setValue("x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void sendingWorks() {
+        fillValidForm();
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Jane");
+        grid.assertCellContent(0, 1, "Hello there");
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+
+        send().assertDisabled();
+
+        name().setValue("Bob");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterSends() {
+        fillValidForm();
+        message().getInputLocator().press("Enter");
+
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void listSurvivesLeavingTheView() {
+        fillValidForm();
+        send().click();
+        GridElement.get(page).assertRowCount(1);
+
+        clickLink("About");
+        assertHeading("About");
+
+        clickLink("Contact");
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAsking() {
+        clickLink("About");
+
+        assertHeading("About");
+        assertEquals(0, page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing"))
+                .count(), "no dialog for an empty form");
+    }
+
+    @Test
+    void keepEditingStaysPut() {
+        name().setValue("Jane");
+        clickLink("About");
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        assertHeading("Contact");
+        assertEquals("Jane", name().getValue());
+    }
+
+    @Test
+    void discardLeaves() {
+        message().setValue("Half written");
+        clickLink("About");
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertHeading("About");
+    }
+}
