+package com.example.views;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        grabFields();
+    }
+
+    private void grabFields() {
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    private Grid<?> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void fillValidForm() {
+        test(name).setValue("Jane");
+        test(email).setValue("jane@example.com");
+        test(message).setValue("Hello there");
+    }
+
+    @Test
+    void viewHasHeadingLinkFormAndGrid() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue($(RouterLink.class).withText("About").exists());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled(), "Send must be enabled on an untouched form");
+        assertTrue($(Grid.class).exists());
+    }
+
+    @Test
+    void emptyFormReportsEveryFailingRule() {
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertFalse($(Notification.class).exists(), "nothing may be sent");
+        assertEquals(0, test(grid()).size());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void malformedEmailIsReported() {
+        test(name).setValue("Jane");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+        assertEquals("Jane", name.getValue(), "what was typed stays");
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        test(name).setValue("Jane");
+        test(phone).setValue("+358 40 123 4567");
+        test(message).setValue("Hello");
+
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        test(name).setValue("Jane");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void exactlyFiveHundredCharactersIsFine() {
+        test(name).setValue("Jane");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(500));
+
+        test(send).click();
+
+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void sendingShowsNotificationClearsFormAndDisablesSend() {
+        fillValidForm();
+        test(send).click();
+
+        assertTrue($(Notification.class).exists());
+        assertTrue(test($(Notification.class).first()).getText().contains("Message sent"));
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Jane", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(send.isEnabled(), "Send is disabled right after a send");
+
+        test(name).setValue("Someone");
+        assertTrue(send.isEnabled(), "editing enables Send again");
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        fillValidForm();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertTrue($(Notification.class).exists());
+    }
+
+    @Test
+    void newestMessageIsFirst() {
+        fillValidForm();
+        test(send).click();
+
+        test(name).setValue("Bob");
+        test(phone).setValue("123");
+        test(message).setValue("Second");
+        test(send).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Bob", test(grid()).getCellText(0, 0));
+        assertEquals("Jane", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        fillValidForm();
+        test(send).click();
+
+        UI.getCurrent().navigate(AboutView.class);
+        assertInstanceOf(AboutView.class, getCurrentView());
+
+        navigate(ContactView.class);
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void sendIsEnabledAgainOnAFreshVisit() {
+        fillValidForm();
+        test(send).click();
+        assertFalse(send.isEnabled());
+
+        UI.getCurrent().navigate(AboutView.class);
+        navigate(ContactView.class);
+        grabFields();
+
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAsking() {
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists(), "no dialog for an empty form");
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void keepEditingStaysOnTheView() {
+        test(name).setValue("Jane");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Jane", $(TextField.class).withLabel("Name").single().getValue());
+    }
+
+    @Test
+    void discardLeavesTheView() {
+        test(message).setValue("Half written");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).exists());
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void navigationFromAnywhereElseAlsoAsks() {
+        test(phone).setValue("123");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+}
